export type Cities = z.output<typeof citiesSchema>;

// ---- query parsing (shared by api2 and the apps) ----

const first = (v: unknown) => (Array.isArray(v) ? v.at(-1) : v);
const blank = (v: unknown) => {
  const x = first(v);
  return x === "" || x === null ? undefined : x;
};

/** Up to this many values in a csv filter (`category=a,b`, `city=1,2`). */
export const MAX_FILTER_VALUES = 30;
/** Search: 2 to 80 characters (SPEC 13c §6.10). */
export const SEARCH_QUERY = { min: 2, max: 80 } as const;
/** Near me: the radius chips, and what the API accepts. */
export const RADIUS_KM = { default: 25, min: 5, max: 100, chips: [5, 10, 25, 50] } as const;

export const platformParam = z.preprocess(blank, z.enum(CATALOGUE_PLATFORMS, { error: "Choose ios, android or web." }).optional());

const csv = (item: z.ZodType<string | number>, what: string) =>
  z.preprocess(
    blank,
    z
      .string()
      .transform((s, ctx) => {
        const parts = s
          .split(",")
          .map((p) => p.trim())
          .filter(Boolean);
        if (parts.length > MAX_FILTER_VALUES) {
          ctx.addIssue({ code: "custom", message: `Pick ${MAX_FILTER_VALUES} or fewer.` });
          return z.NEVER;
        }
        const out: (string | number)[] = [];
        for (const p of parts) {
          const r = item.safeParse(p);
          if (!r.success) {
            ctx.addIssue({ code: "custom", message: `Pick a ${what} from the list.` });
            return z.NEVER;
          }
          out.push(r.data);
        }
        return [...new Set(out)];
      })
      .optional(),
  );

/** A category or group by id or slug. */
const idOrSlug = z.union([z.string().regex(/^\d{1,5}$/).transform(Number), z.string().regex(/^[a-z0-9][a-z0-9-]{1,39}$/)]);
const cityId = z.string().regex(/^\d{1,5}$/).transform(Number);

const intParam = (min: number, max: number, msg: string) => z.preprocess((v) => {
  const x = blank(v);
  return typeof x === "string" && /^\d+$/.test(x) ? Number(x) : x;
}, z.number({ error: msg }).int(msg).min(min, msg).max(max, msg).optional());

const limitParam = intParam(1, PAGE.maxLimit, `Use a limit from 1 to ${PAGE.maxLimit}.`);
const cursorParam = z.preprocess(blank, z.string().max(300, "This page link has expired. Reload the list.").optional());

/** `near=lat,lng` (Philippine bounds with a margin). */
const nearParam = z.preprocess(
  blank,
  z
    .string()
    .transform((s, ctx) => {
      const m = /^\s*(-?\d{1,2}(?:\.\d+)?)\s*,\s*(-?\d{1,3}(?:\.\d+)?)\s*$/.exec(s);
      const lat = m ? Number(m[1]) : NaN;
      const lng = m ? Number(m[2]) : NaN;
      if (!(lat >= 4 && lat <= 22 && lng >= 115 && lng <= 128)) {
        ctx.addIssue({ code: "custom", message: "Pick a place in the Philippines." });
        return z.NEVER;
      }
      return { lat, lng };
    })
    .optional(),
);

export const feedQuerySchema = z
  .strictObject({
    platform: platformParam,
    category: csv(idOrSlug, "category"),
    group: z.preprocess(blank, idOrSlug.optional()),
    city: csv(cityId, "city"),
    near: nearParam,
    radiusKm: intParam(RADIUS_KM.min, RADIUS_KM.max, `Use a radius from ${RADIUS_KM.min} to ${RADIUS_KM.max} km.`),
    q: z.preprocess(
      (v) => {
        const s = blank(v);
        // control and invisible characters are dropped, so the minimum counts what a person typed
        return typeof s === "string" ? searchText(s).replace(/\s+/g, " ").trim() || undefined : s;
      },
      z
        .string()
        .refine((x) => codePoints(x) >= SEARCH_QUERY.min, `Type at least ${SEARCH_QUERY.min} characters.`)
        .refine((x) => codePoints(x) <= SEARCH_QUERY.max, `Use ${SEARCH_QUERY.max} characters or fewer.`)
        .optional(),
    ),
    priceMin: intParam(0, PRICE.maxCentavos, "Enter a price up to ₱1,000,000."),
    priceMax: intParam(0, PRICE.maxCentavos, "Enter a price up to ₱1,000,000."),
    /** `1`: apply the signed-in client's feed preferences where no category or city is given */
    prefs: z.preprocess(blank, z.enum(["1", "0"]).optional()),
    cursor: cursorParam,
    limit: limitParam,
  })
  .refine((v) => v.priceMin === undefined || v.priceMax === undefined || v.priceMin <= v.priceMax, { message: "The lowest price must be below the highest.", path: ["priceMin"] });
export type FeedQuery = z.output<typeof feedQuerySchema>;

