// ---- typed client ----

type Params = Record<string, string | number | boolean | null | undefined>;
const csvOf = (v: readonly (string | number)[] | undefined) => (v && v.length ? v.join(",") : undefined);

export interface FeedParams {
  platform?: CataloguePlatform;
  category?: readonly (string | number)[];
  group?: string | number;
  city?: readonly number[];
  near?: { lat: number; lng: number };
  radiusKm?: number;
  q?: string;
  priceMin?: number;
  priceMax?: number;
  prefs?: boolean;
  cursor?: string | null;
  limit?: number;
}

export function catalogueApi(api: Client) {
  const feedQuery = (p: FeedParams): Params => ({
    platform: p.platform,
    category: csvOf(p.category),
    group: p.group,
    city: csvOf(p.city),
    near: p.near ? `${p.near.lat},${p.near.lng}` : undefined,
    radiusKm: p.radiusKm,
    q: p.q,
    priceMin: p.priceMin,
    priceMax: p.priceMax,
    prefs: p.prefs ? "1" : undefined,
    cursor: p.cursor ?? undefined,
    limit: p.limit,
  });
  const enc = encodeURIComponent;
  return {
    categories: (platform?: CataloguePlatform): Promise<ApiResult<Categories>> => api.get("/v1/categories", { query: { platform }, schema: categoriesSchema }),
    cities: (): Promise<ApiResult<Cities>> => api.get("/v1/cities", { schema: citiesSchema }),
    languages: (): Promise<ApiResult<Languages>> => api.get("/v1/languages", { schema: languagesSchema }),
    feed: (p: FeedParams = {}): Promise<ApiResult<Feed>> => api.get("/v1/services", { query: feedQuery(p), schema: feedSchema }),
    service: (idOrCode: string, platform?: CataloguePlatform): Promise<ApiResult<PublicService>> => api.get(`/v1/services/${enc(idOrCode)}`, { query: { platform }, schema: publicServiceSchema }),
    serviceReviews: (serviceId: string, q: { cursor?: string | null; limit?: number; platform?: CataloguePlatform } = {}): Promise<ApiResult<PublicReviewList>> =>
      api.get(`/v1/services/${enc(serviceId)}/reviews`, { query: { cursor: q.cursor ?? undefined, limit: q.limit, platform: q.platform }, schema: publicReviewListSchema }),
    slots: (serviceId: string, q: { from?: string; to?: string; hours?: number; guests?: number; platform?: CataloguePlatform } = {}): Promise<ApiResult<Slots>> =>
      api.get(`/v1/services/${enc(serviceId)}/slots`, { query: q, schema: slotsSchema }),
    provider: (handle: string, platform?: CataloguePlatform): Promise<ApiResult<ProviderPage>> => api.get(`/v1/providers/${enc(handle)}`, { query: { platform }, schema: providerPageSchema }),
    providerReviews: (handle: string, q: { cursor?: string | null; limit?: number; platform?: CataloguePlatform } = {}): Promise<ApiResult<PublicReviewList>> =>
      api.get(`/v1/providers/${enc(handle)}/reviews`, { query: { cursor: q.cursor ?? undefined, limit: q.limit, platform: q.platform }, schema: publicReviewListSchema }),
    teams: (q: { platform?: CataloguePlatform; city?: readonly number[]; category?: readonly (string | number)[]; cursor?: string | null; limit?: number } = {}): Promise<ApiResult<TeamList>> =>
      api.get("/v1/teams", { query: { platform: q.platform, city: csvOf(q.city), category: csvOf(q.category), cursor: q.cursor ?? undefined, limit: q.limit }, schema: teamListSchema }),
    team: (slug: string, platform?: CataloguePlatform): Promise<ApiResult<TeamPage>> => api.get(`/v1/teams/${enc(slug)}`, { query: { platform }, schema: teamPageSchema }),
    teamReviews: (slug: string, q: { cursor?: string | null; limit?: number; platform?: CataloguePlatform } = {}): Promise<ApiResult<PublicReviewList>> =>
      api.get(`/v1/teams/${enc(slug)}/reviews`, { query: { cursor: q.cursor ?? undefined, limit: q.limit, platform: q.platform }, schema: publicReviewListSchema }),
    feedPrefs: (): Promise<ApiResult<FeedPrefsView>> => api.get("/v1/me/feed-prefs", { schema: feedPrefsSchema }),
    setFeedPrefs: (body: z.input<typeof feedPrefsBodySchema>): Promise<ApiResult<FeedPrefsView>> => api.put("/v1/me/feed-prefs", body, { schema: feedPrefsSchema }),
  };
}
